import { ok, fail } from "#app/lib/envelope.js";
import { getUser } from "#app/users.js";

export function handleGetUser(req, res) {
  const user = getUser(req.params.id);
  if (!user) return fail(res, 404, "not_found", "No such user");
  return ok(res, user);
}
